  raise exception 'Fragmento fuentes_0012 incorrecto; no se guardó';
 end if;
 update public.s911_catalogos set fuentes=jsonb_set(fuentes,'{fragmentos,fuentes_0012}',to_jsonb(v_fragmento),true)
 where sha256='CARGA911:76a45a0894459bdf9aab6365294561d80d5fa4981dbb5ae1073d552ab6ddab9f' and edicion='CARGA_2026-2027';
